late_id":"c45d5331-a1c7-4b52-a30c-0a08724b66ca","source_id":"289d9e56-a6a4-4754-a772-a94239bda29a","provider_hash":"c95e9d3c93b2dcc61c4a667e2451466e5937ac104838d00cae7924aea75fbd50","title_hash":"916cd315df964d7324ebde15c1a402b024293f01a748df033ff5656428ddc951","description_hash":"c2b9202d5f591c96481fe9d0d35fd3feb86d2fc12cec837356e1f2536dba2d09","syllabus_hash":"da50aa40b80ec5031f1fa44af499828f27318187e1a5cc8797a16cc2baeacffb","prerequisites_hash":"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","notes_hash":"cfb42aa0230007c517a66aa155ee5f5777db65840405727b943a499240eceda2","title":"PTE2 · Penetration Tester / Ethical Hacker - Aufbaukurs","description":"Kursbaustein PTE2: Penetration Tester / Ethical Hacker - Aufbaukurs. Dauer laut Bausteinbeschreibung: 10 Tage, 80 Std.","notes":"Historischer Bausteininhalt gemäß referenziertem Quelldokument. Genannte Prüfungskennungen sind keine Bestätigung aktueller Zertifizierungsanforderungen."}]$neutral_rows$::jsonb; entry jsonb;
begin
 for entry in select value from jsonb_array_elements(rows) loop
  update public.course_templates t set title=entry->>'title',description=entry->>'description'
  where t.id=(entry->>'template_id')::uuid
   and t.building_block_id=(entry->>'id')::uuid
   and t.building_block_source_id=(entry->>'source_id')::uuid
   and t.archived_at is null
   and encode(sha256(convert_to(t.title,'UTF8')),'hex')=entry->>'title_hash'
   and encode(sha256(convert_to(t.description,'UTF8')),'hex')=entry->>'description_hash'
   and encode(sha256(convert_to(t.syllabus,'UTF8')),'hex')=entry->>'syllabus_hash'
   and encode(sha256(convert_to(t.prerequisites,'UTF8')),'hex')=entry->>'prerequisites_hash'
   and not exists(select 1 from public.course_runs r where r.template_id=t.id)
   and not exists(select 1 from public.course_template_topics x where x.template_id=t.id)
   and not exists(select 1 from public.audit_events a where a.resource_id=t.id and a.action='course.template.saved');
  update public.building_blocks b set
   provider=case when encode(sha256(convert_to(b.provider,'UTF8')),'hex')=entry->>'provider_hash' then 'course-catalogue' else b.provider end,
   description=case when encode(sha256(convert_to(b.description,'UTF8')),'hex')=entry->>'description_hash' then entry->>'description' else b.description end,
   notes=case when encode(sha256(convert_to(b.notes,'UTF8')),'hex')=entry->>'notes_hash' then entry->>'notes' else b.notes end
  where b.id=(entry->>'id')::uuid;
 end loop;
end;$neutral_import$;

